use axum::{body::Body, http::Request, routing::get, Router};
use tower::ServiceExt;

#[tokio::main]
async fn main() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new().nest("/nested", nested_routes).merge(other_router);

    let res = app
        .oneshot(Request::builder().uri("/nested/foo").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(http_body_util::BodyExt::to_string(res.into_body()).await.unwrap(), "fallback");

    let res = app
        .clone()
        .oneshot(Request::builder().uri("/nested/some-route").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(http_body_util::BodyExt::to_string(res.into_body()).await.unwrap(), "nested");

    let res = app
        .oneshot(Request::builder().uri("/other").body(Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(http_body_util::BodyExt::to_string(res.into_body()).await.unwrap(), "other");

    println!("issue scenario OK");
}

use axum::{routing::get, Router};
use http_body_util::{BodyExt, Empty};
use tower::ServiceExt;

#[tokio::test]
async fn issue_scenario() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new().nest("/nested", nested_routes).merge(other_router);

    let res = app
        .clone()
        .oneshot(http::Request::builder().uri("/nested/foo").body(axum::body::Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.into_body().collect().await.unwrap().to_bytes(), "fallback");

    let res = app
        .clone()
        .oneshot(http::Request::builder().uri("/nested/some-route").body(axum::body::Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.into_body().collect().await.unwrap().to_bytes(), "nested");

    let res = app
        .oneshot(http::Request::builder().uri("/other").body(axum::body::Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.into_body().collect().await.unwrap().to_bytes(), "other");

    let _: Option<Empty<axum::body::Bytes>> = None;
}

#[tokio::test]
async fn issue_scenario_with_outer_fallback() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new()
        .nest("/nested", nested_routes)
        .fallback(|| async { "outer fallback" })
        .merge(other_router);

    let res = app
        .oneshot(http::Request::builder().uri("/nested/foo").body(axum::body::Body::empty()).unwrap())
        .await
        .unwrap();
    assert_eq!(res.into_body().collect().await.unwrap().to_bytes(), "fallback");
}

