use axum::{routing::get, Router};

#[tokio::test]
async fn issue_scenario() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new().nest("/nested", nested_routes).merge(other_router);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });

    let client = reqwest::Client::new();

    let res = client
        .get(format!("http://{addr}/nested/foo"))
        .send()
        .await
        .unwrap();
    assert_eq!(res.text().await.unwrap(), "fallback");

    let res = client
        .get(format!("http://{addr}/nested/some-route"))
        .send()
        .await
        .unwrap();
    assert_eq!(res.text().await.unwrap(), "nested");

    let res = client.get(format!("http://{addr}/other")).send().await.unwrap();
    assert_eq!(res.text().await.unwrap(), "other");
}

#[tokio::test]
async fn issue_scenario_with_outer_fallback() {
    let nested_routes = Router::new()
        .route("/some-route", get(|| async { "nested" }))
        .fallback(|| async { "fallback" });

    let other_router = Router::new().route("/other", get(|| async { "other" }));

    let app = Router::new()
        .nest("/nested", nested_routes)
        .fallback(|| async { "outer fallback" })
        .merge(other_router);

    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });

    let res = reqwest::get(format!("http://{addr}/nested/foo")).await.unwrap();
    assert_eq!(res.text().await.unwrap(), "fallback");
}
